    { t: { ar: "أنواع الأخطاء", en: "Error types" }, d: { ar: "صياغة يوقف · تشغيل يتوقف فجأة · منطقي يعمل ويعطي خطأ", en: "Syntax stops it, runtime halts it suddenly, logic runs and returns the wrong answer" } },
    { t: { ar: "Debugging", en: "Debugging" }, d: { ar: "تتبّع الخطأ وتصحيحه: غيّر شيئاً واحداً واطبع القيم", en: "Tracing and fixing errors: change one thing and print values" } }
